export const STORYTELLER_PALETTES = {
  green: {
    ramp: ["#8fe3bb", "#6cdaa5", "#47d18f", "#2fbd79", "#269a62", "#1d754b"],
    glow: "#2fbd79",
  },
  violet: {
    ramp: ["#a68fe3", "#8a6cda", "#6c47d1", "#562fbd", "#46269a", "#351d75"],
    glow: "#562fbd",
  },
  amber: {
    ramp: ["#e3c78f", "#dab66c", "#d1a447", "#bd8e2f", "#9a7426", "#75581d"],
    glow: "#bd8e2f",
  },
}

// Where the drawing's own eye placeholders sat: their centres and radii,
// measured from the two traced ellipses in the source SVG. The canonical
// eye mounts exactly here, so the eyes land where Kimia drew them.
export const STORYTELLER_EYES = [
  { cx: 62.27, cy: 207.32, r: 7.95 },
  { cx: 131.31, cy: 210.13, r: 8.37 },
]

// The soft-blur filter the glow aura paints through, namespaced like the
// eye gradients so several storyteller SVGs on one page never collide.
const glowId = (prefix) => `${prefix}storyteller-glow`

/* WHY THE BODY AND EYES ARE SEPARATE COMPONENTS (2026-07-26): when
 * anything animates INSIDE an <svg>, the browser re-rasterises that
 * svg's content — and this body is six enormous traced paths plus a
 * Gaussian-blur aura, expensive to redraw. With the blinking eyes in
 * the same svg, every blink would re-blur the whole figure for every
 * animation frame of the squash, a jank spike on modest hardware
 * repeating each cycle. So the asset ships as TWO stacked SVGs:
 * <StorytellerBody/> (heavy, static — painted once) and
 * <StorytellerEyes/> (two small blinking eyes in their own
 * featherweight <svg> laid exactly over it, sharing the same viewBox
 * so the eyes land where Kimia drew them). Keep this split wherever
 * the storyteller is drawn.
 */

// Defs for the BODY svg: just the aura's blur filter.
export function StorytellerBodyDefs({ prefix = '' }) {
  return (
    <filter id={glowId(prefix)} x="-40%" y="-40%" width="180%" height="180%">
      <feGaussianBlur stdDeviation="6" />
    </filter>
  )
}

// The heavy, static half: glow aura first (the bottom layer blurred and
// filled the body colour — a friend's glow IS its body colour, §3),
// then the six shade layers. No animation may ever live in this svg.
export function StorytellerBody({ palette = STORYTELLER_GREYS, prefix = '' }) {
  return (
    <g>
      <path
        d={STORYTELLER_LAYERS[0]}
        fill={palette.glow}
        opacity="0.8"
        filter={`url(#${glowId(prefix)})`}
      />
      {STORYTELLER_LAYERS.map((d, i) => (
        <path key={i} d={d} fill={palette.ramp[i] ?? palette.ramp[palette.ramp.length - 1]} />
      ))}
    </g>
  )
}

// The light, animated half: the two canonical yellow eyes, each in its
// own .storyteller-eye-blink wrapper so the idle blink (index.css)
// squashes it around its own centre. Render inside an <svg> with the
// storyteller viewBox and one <EyeDefs prefix/> (eye.jsx) in its defs.
export function StorytellerEyes({ prefix = '' }) {
  return (
    <g>
      {STORYTELLER_EYES.map((eye, i) => (
        <g key={i} className="storyteller-eye-blink">
          <Eye cx={eye.cx} cy={eye.cy} r={eye.r} prefix={prefix} />
        </g>
      ))}
    </g>
  )
}
